export const JOURNEY: JourneyStep[] = [
  { title: L('发送', 'Send'), nodes: ['agent', 'api'], pill: 'express', route: [['send', 1]],
    body: L('客服按下发送后，浏览器通过 HTTPS 把消息连同一个唯一的消息编号交给服务器。服务器先核对登录状态、对这段对话的权限和发送频率（每人每分钟最多 120 条）。', 'When the agent presses Send, the browser passes the message and its own unique message ID to the server over HTTPS. The server first checks the sign-in, the agent’s access to this conversation and the sending rate (at most 120 messages a minute per person).'),
    tech: L('HTTPS · Express · 共享校验规则 · Redis 频率限制', 'HTTPS · Express · shared validation · Redis rate limit') },
  { title: L('保存', 'Save'), nodes: ['agent', 'api', 'db'], pill: 'express', route: [['save', 1], ['save', -1], ['ack', 1]],
    body: L('消息、它在对话中的顺序号和一条「待通知」记录，在同一个 PostgreSQL 事务中保存：要么全部成功，要么都不保存。保存成功后，客服才看到「已发送」。用同一个编号重试只会拿回原来那条消息，不会重复。', 'The message, its place in the conversation and a “to announce” record are saved in one PostgreSQL transaction: all of it or none of it. Only then does the agent see Sent. Retrying with the same ID returns the original message, never a copy.'),
    tech: L('PostgreSQL 事务 · 顺序号 · outbox 记录 · 幂等编号', 'PostgreSQL transaction · sequence number · outbox row · idempotency key') },
  { title: L('通知后台', 'Announce'), nodes: ['db', 'worker', 'redis'], pill: '', route: [['notify', 1], ['publish', 1]],
    body: L('事务一提交，PostgreSQL 立即唤醒后台 Worker（另有每 500 毫秒一次的备用检查）。Worker 向 Redis 发布一条「有更新」的通知，其中不含消息内容。', 'As soon as the transaction commits, PostgreSQL wakes the background worker (a check every 500 ms is the fallback). The worker publishes a “something changed” note to Redis. The note contains no message text.'),
    tech: L('PostgreSQL NOTIFY · Worker · Redis 发布', 'PostgreSQL NOTIFY · worker · Redis publish') },
  { title: L('实时提醒', 'Notify'), nodes: ['redis', 'api', 'visitor'], pill: 'socket', route: [['subscribe', 1], ['sync', 1]],
    body: L('每台 API 服务器都订阅了 Redis。收到通知后，它通过 Socket.io 的实时连接，只提醒有权查看这段对话的人：访客、接待客服以及所有者和管理员。', 'Every API server listens on Redis. When the note arrives, each one uses its Socket.io live connections to nudge only the people allowed to see this conversation: the visitor, the assigned agent, and owners and admins.'),
    tech: L('Redis 订阅 · Socket.io 房间 · WebSocket', 'Redis subscribe · Socket.io rooms · WebSocket') },
  { title: L('获取并显示', 'Fetch and show'), nodes: ['visitor', 'api', 'db'], pill: 'express', route: [['fetch', 1], ['read', -1], ['read', 1], ['fetch', -1]],
    body: L('访客的浏览器请求「最后一条之后的新消息」。服务器在 PostgreSQL 中再次核对权限后返回，消息随即出现在屏幕上。「已送达」「已读」回执也沿同样的路线回到客服。', 'The visitor’s browser asks for anything newer than the last message it has. The server checks access against PostgreSQL again and returns it, and the message appears. Delivered and read receipts travel back to the agent the same way.'),
    tech: L('HTTP · 从最后的顺序号续读 · 每次读取重新授权', 'HTTP · read after the last sequence · access re-checked on every read') },
];
