export const DG_DESC: Text = L('客服的浏览器把消息发给 Node.js API；API 将消息保存到 PostgreSQL 并向客服确认；PostgreSQL 唤醒 Worker，Worker 向 Redis 发布不含内容的通知；API 从 Redis 收到通知，通过 Socket.io 提醒访客的浏览器；访客的浏览器再向 API 获取新消息，API 核对权限后从 PostgreSQL 读取。', 'The agent’s browser sends the message to the Node.js API, which saves it in PostgreSQL and confirms to the agent. PostgreSQL wakes the worker, which publishes a content-free note to Redis. The API receives the note from Redis and nudges the visitor’s browser over Socket.io. The visitor’s browser then fetches the new message from the API, which checks access and reads it from PostgreSQL.');
